<script>$(function(){let filter='all',page=1,last=1,timer;$('#createdBy').select2({width:'100%',dropdownParent:$('#complaintFilterDrawer')});$('#searchToggle').click(function(){$('#complaintSearch').addClass('is-open');setTimeout(()=>$('#search').focus(),100)});$('#search').on('blur',function(){if(!this.value)$('#complaintSearch').removeClass('is-open')});const esc=v=>$('<div>').text(v||'N/A').html();const params=()=>({filter,page,search:$('#search').val(),created_by:$('#createdBy').val(),date_from:$('#dateFrom').val(),date_to:$('#dateTo').val()});function closeDrawer(){$('#complaintFilterDrawer').removeClass('is-open').attr('aria-hidden','true');$('body').removeClass('fk-filter-open');$('.fk-filter-backdrop').remove()}function load(){$.get("{{route('complaints.mobile-list')}}",params(),function(r){Object.keys(r.counts).forEach(k=>$('#count-'+k).text(r.counts[k]));$('#recordCount').text(r.counts.all+' records');last=r.last_page;$('#tableMeta').text('Live directory · page '+r.current_page+' of '+Math.max(r.last_page,1));$('#complaintRows').html(r.data.map((x,i)=>`<tr><td>${(r.current_page-1)*25+i+1}</td><td>${esc(x.date)}</td><td><a href="${x.detail_url}" class="text-info font-weight-bold">${esc(x.number)}</a></td><td>${esc(x.dealer)}</td><td>${esc(x.end_user)}</td><td>${esc(x.mobile)}</td><td>${esc(x.category)}</td><td>${esc(x.size)}</td><td>${esc(x.batch)}</td><td><span title="${esc(x.description)}">${esc(x.description)}</span></td><td>${esc(x.received_through)}</td><td><span class="badge badge-info">${esc(x.status)}</span></td></tr>`).join(''));$('#empty').toggle(!r.data.length);$('#prev').prop('disabled',page<=1);$('#next').prop('disabled',page>=last)}).fail(()=>{$('#complaintRows').empty();$('#empty').text('Unable to load complaints').show()})}$('.status-filter').click(function(){filter=$(this).data('filter');page=1;$('.status-filter').removeClass('btn-info').addClass('btn-outline-info');$(this).removeClass('btn-outline-info').addClass('btn-info');load()});$('#s